import hashlib
import math

class BloomFilter:
    """
    A Bloom filter implementation with methods for adding items and checking membership.

    This implementation uses a bit array represented by an integer and multiple hash functions
    derived from the input. The number of bits and the number of hash functions are calculated
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._optimal_hash_count(expected_items, self.size)
        self.bit_array = 0

    def _optimal_size(self, expected_items: int, false_positive_rate: float) -> int:
        """Calculate the optimal size of the bit array in bits."""
        return math.ceil((-expected_items * math.log(false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_hash_count(self, expected_items: int, size: int) -> int:
        """Calculate the optimal number of hash functions."""
        return math.ceil((size / expected_items) * math.log(2))

    def _hash(self, item: str, seed: int) -> int:
        """Generate a hash for the item based on the seed."""
        hash_object = hashlib.md5((item + str(seed)).encode())
        return int(hash_object.hexdigest(), 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for seed in range(self.hash_count):
            bit_index = self._hash(item, seed)
            self.bit_array |= (1 << bit_index)

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom filter."""
        for seed in range(self.hash_count):
            bit_index = self._hash(item, seed)
            if not (self.bit_array & (1 << bit_index)):
                return False
        return True

